import{_ as a,a0 as n,w as d,s as l,ao as i,I as t,x as o,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何雙啓動 Fedora 和 Windows | LCTT x X-CMD","titleTemplate":false,"description":"如何雙啓動 Fedora 和 Windows | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何雙啓動 Fedora 和 Windows | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何雙啓動 Fedora 和 Windows | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20210711 How to Dual Boot Fedora and Windows","title":"如何雙啓動 Fedora 和 Windows","tag":"202203","desc":""},"relativePath":"202203/20210711 How to Dual Boot Fedora and Windows.md","filePath":"[post].md"}'),m={name:"202203/20210711 How to Dual Boot Fedora and Windows.md"};function u(w,s,f,g,b,F){const p=n("Link");return d(),l("div",null,[s[28]||(s[28]=i('<h1 id="如何雙啓動-fedora-和-windows" tabindex="-1">如何雙啓動 Fedora 和 Windows <a class="header-anchor" href="#如何雙啓動-fedora-和-windows" aria-label="Permalink to “如何雙啓動 Fedora 和 Windows”">​</a></h1><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-windows-dual-boot.jpg?resize=800%2C450&amp;ssl=1" alt=""></p><blockquote><p>這篇詳細的教程一步一步地向你展示 <strong>如何雙啓動 Fedora Linux 和 Windows 10</strong>，附有適當的截圖。</p></blockquote><p>雙啓動 Linux 和 Windows 是一種完全享受這兩款操作系統的流行方式。你可以在同一個硬件系統上安裝 Linux 和 Windows 兩款系統，並在你啓動你的硬件系統時選擇使用哪款操作系統。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/dual-boot-grub-screen-fedora-windows.jpg?resize=800%2C350&amp;ssl=1" alt="On the grub screen, you can select the operating system"></p><p>如果你有一個已經安裝 Windows 的系統，你將在這篇教程中學習如何在 Windows 的旁側安裝 Fedora 。</p><h3 id="在-windows-的旁側安裝-fedora" tabindex="-1">在 Windows 的旁側安裝 Fedora <a class="header-anchor" href="#在-windows-的旁側安裝-fedora" aria-label="Permalink to “在 Windows 的旁側安裝 Fedora”">​</a></h3><p>這篇教程是在一款已經安裝 Windows，採用 GPT 分區和 UEFI 啓動的硬件系統的基礎上執行的。它應該也適用於其它的帶有 MBR 分區和傳統 BIOS 的硬件系統，但是我不能確認這一點。</p><p>注意：如果你的 Windows 系統使用 BitLocker 加密，在你安裝 Fedora 前禁用它會是一個好主意。</p><h4 id="必要條件" tabindex="-1">必要條件 <a class="header-anchor" href="#必要條件" aria-label="Permalink to “必要條件”">​</a></h4><p>這裏是你需要遵循這篇教程的東西:</p><ul><li>一個已預裝 Windows 的系統</li><li>良好的互聯網連接速度</li><li>一個至少 4 GB 大小的 USB 接口設備（U 盤）</li><li>可選: 用於備份你的 Windows 現有數據的外部 USB 磁盤。</li><li>可選: Windows 恢復或可啓動磁盤（如果你偶遇一些嚴重的啓動問題，你可以修復它）。</li></ul><p>讓我們看看步驟。</p><h4 id="步驟-1-製作-windows-系統的數據備份-可選" tabindex="-1">步驟 1: 製作 Windows 系統的數據備份 [可選] <a class="header-anchor" href="#步驟-1-製作-windows-系統的數據備份-可選" aria-label="Permalink to “步驟 1: 製作 Windows 系統的數據備份 [可選]”">​</a></h4><p>備份總會是一個好主意。因為你將要處理磁盤分區。在一些罕見的不幸情況下，假設你出錯並刪除了錯誤的分區，你將丟失你的數據。</p><p>最簡單的方法是將文檔、視頻、音樂、圖片和其它的文件夾中的數據複製到一塊外部 USB 磁盤中。你可以使用一個外部的機械硬盤（傳輸速度較慢，但是價格較便宜）或固態硬盤（傳輸速度較快，但是價格較昂貴），並將重要的文件和文件夾複製到其中。</p><h4 id="步驟-2-為-fedora-的安裝準備一些可用的空間" tabindex="-1">步驟 2: 為 Fedora 的安裝準備一些可用的空間 <a class="header-anchor" href="#步驟-2-為-fedora-的安裝準備一些可用的空間" aria-label="Permalink to “步驟 2: 為 Fedora 的安裝準備一些可用的空間”">​</a></h4><p>你需要創建一個分區，你將在其中安裝 Fedora 。如果你只有一個 C 驅動器，縮小它的分區。如果你有 D、E 或 F 等多個驅動器，確保你可以移動這些驅動器中的數據到一些其它的分區中，刪除或縮小其中的一個驅動器。超過 40 GB 的驅動器分區都能有足夠的空間來安裝安裝 Fedora 。</p><p>在 Windows 的菜單中，搜索 “磁盤分區” 並轉到 “創建並格式化磁盤分區”。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/03/disc-management-windows.png?resize=800%2C561&amp;ssl=1" alt=""></p><p>在磁盤管理工具中，右鍵單件你想要分區的驅動器，並選擇 “縮小卷”。</p><p>如果你只有一個像這樣的分區，你需要為 Linux 騰出一些可用的空間。如果你有一些空間相當大的分區，請使用除 C 驅動器分區外的分區，因為它會擦除數據。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/04/making-free-space-for-dual-boot.jpg?resize=1226%2C728&amp;ssl=1" alt=""></p><h4 id="步驟-3-在-windows-中製作一個-fedora-的臨場-usb" tabindex="-1">步驟 3: 在 Windows 中製作一個 Fedora 的臨場 USB <a class="header-anchor" href="#步驟-3-在-windows-中製作一個-fedora-的臨場-usb" aria-label="Permalink to “步驟 3: 在 Windows 中製作一個 Fedora 的臨場 USB”">​</a></h4>',24)),t("p",null,[s[1]||(s[1]=o("現在，這個步驟可以通過不同的方法來完成。你可以下載 ISO 並使用 ",-1)),r(p,{href:"https://itsfoss.com/install-etcher-linux/"},{default:e(()=>[...s[0]||(s[0]=[o("Etcher",-1)])]),_:1}),s[2]||(s[2]=o(" 或 Rufus 或一些其它的工具來將 ISO 鏡像寫入 USB 磁盤。",-1))]),s[29]||(s[29]=t("p",null,[o("不過，Fedora 提供了一個用於下載 ISO 鏡像和製作 "),t("ruby",null,[o("臨場 USB"),t("rt",null,"Live USB")]),o(" 的專用工具。我將在這篇教程中使用它。Fedora 團隊在創建這個工具時付出了很多艱難的努力，因此為什麼不使用它呢。")],-1)),s[30]||(s[30]=t("p",null,[o("但是，首先, "),t("strong",null,"插入 USB 接口設備"),o("。現在，轉到 Fedora 的下載頁面：")],-1)),t("ul",null,[t("li",null,[r(p,{href:"https://getfedora.org/en/workstation/download/"},{default:e(()=>[...s[3]||(s[3]=[o("下載 Fedora",-1)])]),_:1})])]),s[31]||(s[31]=i('<p>你將看到針對 Windows 版本的下載 “Fedora Media Writer” 工具的選項。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/download-fedora-media-writer-tool.png?resize=800%2C373&amp;ssl=1" alt=""></p><p>它將下載一個 exe 文件。在下載完成後，轉到你所下載到的文件夾，並雙擊 <code>FedoraMediaWriter.exe</code> 文件來安裝 “Fedora Media Writer” 工具。只需要重複點擊 “<ruby>下一步<rt>next</rt></ruby> 。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-Fedora-Media-Writer-tool-Windows.png?resize=745%2C581&amp;ssl=1" alt=""></p><p>在安裝完成後，運行 “Fedora Media Writer” 工具。但是在此之前，<strong>確保你已經插入 USB 設備</strong>。</p><p>它將給予你安裝各種 Fedora 版本的選項。針對桌面機，選擇<ruby>工作站<rt>Workstation</rt></ruby>版本。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-media-writer-1.png?resize=800%2C425&amp;ssl=1" alt=""></p><p>在接下來的屏幕中，你將會得到一個創建臨場 USB 的選項。當你點擊這個按鈕時，它將開始下載 ISO 文件。它也將識別出你所插入的 USB 接口設備。</p><p>你需要良好的互聯網訪問速度來在一段時間內順暢地下載 2GB 大小的 ISO 文件。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-media-writer-2.jpg?resize=800%2C422&amp;ssl=1" alt=""></p><p>在下載 ISO 後，它會自動地對其進行檢驗，並給予你將 ISO 鏡像寫入到 USB 磁盤的選項，例如，創建臨場 USB 。點擊 “<ruby>寫入到磁盤<rt>Write to Disk</rt></ruby>” 按鈕。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/writing-fedora-iso-to-usb-with-Fedora-Media-Writer-Tool.png?resize=800%2C285&amp;ssl=1" alt=""></p><p>它將花費幾分鐘來完成安裝過程。它顯示 “<ruby>完成<rt>Finished</rt></ruby>” 信息後，你可以關閉 “Fedora Media Writer” 工具了。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedoa-live-usb-with-fedora-media-writer.png?resize=800%2C300&amp;ssl=1" alt=""></p><p>很好！現在你已經準備好了 Fedora 臨場 USB 。現在是時候使用它來安裝帶有圖形用户界面的 Fedora 了。</p><h4 id="步驟-4-從-臨場-usb-啓動並安裝-fedora" tabindex="-1">步驟 4: 從 臨場 USB 啓動並安裝 Fedora <a class="header-anchor" href="#步驟-4-從-臨場-usb-啓動並安裝-fedora" aria-label="Permalink to “步驟 4: 從 臨場 USB 啓動並安裝 Fedora”">​</a></h4>',16)),t("p",null,[s[5]||(s[5]=o("一些系統不允許你在使用安全啓動的情形下從臨場 USB 啓動。如果你是這種情況的話，請 ",-1)),r(p,{href:"https://itsfoss.com/disable-secure-boot-windows/"},{default:e(()=>[...s[4]||(s[4]=[o("禁用安全啓動",-1)])]),_:1}),s[6]||(s[6]=o("。",-1))]),s[32]||(s[32]=i('<p>在處於顯示硬件系統製造商徽標的屏幕期間，按下 <code>F2</code> 或 <code>F10</code> 或 <code>F12</code> 按鍵。如果你不確定是哪個按鍵，你可以逐個嘗試。但是，你要 <strong>快速地</strong> 按下按鍵 ，否則它將會啓動到操作系統之中。</p><p>不同品牌計算機的按鍵是不同的。一些計算機甚至可能使用 <code>Esc</code> 或 <code>Del</code> 按鍵來完成此目的。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/04/acer-predator-boot.jpg?resize=800%2C600&amp;ssl=1" alt="Quickly press F2, F10 or F12 keys at the screen showing your system manufacturer’s logo"></p>',3)),t("p",null,[s[8]||(s[8]=o("在一些罕見的情況下，你可能需要 ",-1)),r(p,{href:"https://itsfoss.com/access-uefi-settings-windows-10/"},{default:e(()=>[...s[7]||(s[7]=[o("在 Windows 中訪問 UEFI 啓動設置",-1)])]),_:1}),s[9]||(s[9]=o("。",-1))]),s[33]||(s[33]=i('<p>在 BIOS 設置中，通常，你應該會看到像這樣的屏幕。在這裏，你可以使用箭頭按鍵來向下移動到 USB 選項，並按下回車鍵來從 USB 啓動。請注意，在不同的系統中，這一屏幕可能會看起來有所不同。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/06/select-boot-from-live-usb.jpg?resize=800%2C330&amp;ssl=1" alt=""></p><p>如果一切順利，你應該會看到像下面的一個屏幕。選擇第一個選項 “<ruby>啓動 Fedora 工作站<rt>Start Fedora Workstation</rt></ruby>”：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-live-screen.jpg?resize=800%2C350&amp;ssl=1" alt=""></p><p>在數秒後，你應該會啓動到 Fedora 臨場會話期間，並會看到嘗試或安裝它的選項。選擇 “<ruby>安裝到硬盤<rt>Install to Hard Drive</rt></ruby>” 。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/Fedora-install-screen.jpg?resize=800%2C450&amp;ssl=1" alt=""></p><p>它會要求選擇安裝過程的語言選項。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-fedora-1.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>接下來的屏幕是很重要的。如果你已經在 “步驟 2” 中創建了可用的空間，你應該能夠點擊 “<ruby>開始安裝<rt>Begin Installation</rt></ruby>” 。如果你在“<ruby>系統<rt>SYSTEM</rt></ruby>”下的磁盤圖標上看到一個感嘆號，單擊它，並查看你能夠在這裏使用哪種磁盤配置。</p><p>如果你有多個磁盤，你可以為 Fedora 選擇使用哪個磁盤。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-fedora-2.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>選擇磁盤，並點擊“<ruby>完成<rt>Done</rt></ruby>” 。現在，你應該會看到一條警告信息。在我的實例中，我沒有在 “步驟 2” 中創建可用的空間，因此它會抱怨這裏沒有足夠的可用的空間來安裝 Fedora 。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-fedora-3.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>我點擊 “<ruby>回收空間<rt>Reclaim space</rt></ruby>” ，並縮小在這裏的 Windows 分區。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-fedora-4.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>在這以後，將出現 “<ruby>開始安裝<rt>Begin Installation</rt></ruby>” 選項，開啓安裝過程。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-fedora-5.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>現在，它只是一個需要耐心等待的遊戲了。將花費數分鐘來提取文件並安裝它們。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-fedora-6.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>當過程完成後，你將看到 “<ruby>結束安裝<rt>Finish Installation</rt></ruby>” 按鈕，點擊它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/installing-fedora-7.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>你將回到 Fedora 臨場會話期間。單擊右上角的下拉菜單並選擇 “<ruby>重新啓動<rt>Restart</rt></ruby>” 。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/restart-gnome-fedora.jpg?resize=799%2C439&amp;ssl=1" alt=""></p>',23)),t("p",null,[s[11]||(s[11]=o("現在，當系統啓動時，你應該會看到帶有啓動到 Fedora 和 Windows 選項的 ",-1)),r(p,{href:"https://itsfoss.com/what-is-grub/"},{default:e(()=>[...s[10]||(s[10]=[o("Grub 啓動器",-1)])]),_:1}),s[12]||(s[12]=o("。",-1))]),s[34]||(s[34]=i('<p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/dual-boot-grub-screen-fedora-windows.jpg?resize=800%2C350&amp;ssl=1" alt=""></p><h4 id="步驟-5-完成-fedora-安裝" tabindex="-1">步驟 5: 完成 Fedora 安裝 <a class="header-anchor" href="#步驟-5-完成-fedora-安裝" aria-label="Permalink to “步驟 5: 完成 Fedora 安裝”">​</a></h4><p>至此你幾乎完成了安裝。你注意到 Fedora 沒有要求你輸入用户名和密碼了嗎？很多發行版（像 Ubuntu ）在安裝期間會要求你創建一個管理用户。作為另一種方式，Fedora 會在你第一次登錄到所安裝的系統時給予你這個選項。</p><p>當你第一次登錄時，它會運行一次設置，並創建用户名和密碼來作為這次初始化設置的一部分。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-setup-1.png?resize=800%2C575&amp;ssl=1" alt=""></p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-setup-2.png?resize=800%2C593&amp;ssl=1" alt=""></p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-setup-3.png?resize=800%2C591&amp;ssl=1" alt=""></p><p>在你完成後，你已經用上 Fedora Linux 了。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/07/fedora-setup-completed.jpg?resize=800%2C500&amp;ssl=1" alt=""></p><p>就這樣，你可以在同一個硬件系統上以雙啓動的模式來享受 Fedora Linux 和 Windows 。</p><p>如果你在學習這篇教程時有一些問題或者你正在面對一些重大難題，請在評論系統中告訴我。</p><hr>',12)),t("p",null,[s[14]||(s[14]=o("via: ",-1)),r(p,{href:"https://itsfoss.com/dual-boot-fedora-windows/"},{default:e(()=>[...s[13]||(s[13]=[o("https://itsfoss.com/dual-boot-fedora-windows/",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=o("作者：",-1)),r(p,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>[...s[15]||(s[15]=[o("Abhishek Prakash",-1)])]),_:1}),s[20]||(s[20]=o(" 選題：",-1)),r(p,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[16]||(s[16]=[o("lujun9972",-1)])]),_:1}),s[21]||(s[21]=o(" 譯者：",-1)),r(p,{href:"https://github.com/robsean"},{default:e(()=>[...s[17]||(s[17]=[o("robsean",-1)])]),_:1}),s[22]||(s[22]=o(" 校對：",-1)),r(p,{href:"https://github.com/wxy"},{default:e(()=>[...s[18]||(s[18]=[o("wxy",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=o("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[23]||(s[23]=[o("LCTT",-1)])]),_:1}),s[26]||(s[26]=o(" 原創編譯，",-1)),r(p,{href:"https://linux.cn/"},{default:e(()=>[...s[24]||(s[24]=[o("Linux中國",-1)])]),_:1}),s[27]||(s[27]=o(" 榮譽推出",-1))])])}const T=a(m,[["render",u]]);export{h as __pageData,T as default};
